public final class WallArtImageChunkPacket implements IMessage{String hash="";int index,total,fullLength;byte[] bytes;boolean valid;public WallArtImageChunkPacket(){}public WallArtImageChunkPacket(String h,int i,int t,int f,byte[] b){hash=h;index=i;total=t;fullLength=f;bytes=b;valid=true;}public void fromBytes(ByteBuf b){valid=false;if(b.readableBytes()<80)return;byte[] h=new byte[64];b.readBytes(h);hash=new String(h,Charset.forName("US-ASCII"));index=b.readInt();total=b.readInt();fullLength=b.readInt();int n=b.readInt();int maxChunks=(WallArtConstants.MAX_PROCESSED_IMAGE_BYTES+WallArtConstants.CHUNK_BYTES-1)/WallArtConstants.CHUNK_BYTES;if(!WallArtConstants.validHash(hash)||total<1||total>maxChunks||index<0||index>=total||fullLength<1||fullLength>WallArtConstants.MAX_PROCESSED_IMAGE_BYTES||n<1||n>WallArtConstants.CHUNK_BYTES||n>b.readableBytes())return;bytes=new byte[n];b.readBytes(bytes);valid=b.readableBytes()==0;}public void toBytes(ByteBuf b){b.writeBytes(hash.getBytes(Charset.forName("US-ASCII")));b.writeInt(index);b.writeInt(total);b.writeInt(fullLength);b.writeInt(bytes.length);b.writeBytes(bytes);}public static final class Handler implements IMessageHandler<WallArtImageChunkPacket,IMessage>{@SideOnly(Side.CLIENT) public IMessage onMessage(WallArtImageChunkPacket m,MessageContext c){if(m.valid)com.hfr.main.MainRegistry.proxy.acceptWallArtChunk(m.hash,m.index,m.total,m.fullLength,m.bytes);return null;}}}
